// Run a Spring Boot container with resource limits and namespace isolation
// This demonstrates cgroups (memory/CPU limits) and implied namespace isolation

docker run -d \
  --name order-service \
  --memory="512m" \
  --cpus="1.5" \
  -p 8080:8080 \
  order-service:latest

// Inside the container, check what processes are visible
docker exec order-service ps aux
// Output shows ONLY container processes:
// PID 1: java -jar order-service.jar
// PID 42: ps aux
// The container can't see host processes or other containers

// From the host, the same Java process has a different PID
ps aux | grep order-service
// Shows: user 12847 java -jar order-service.jar
// The host sees it as a regular process, but namespaces give it an isolated view

// The memory and cpus flags use cgroups under the hood
// Kernel enforces these limits; container can't exceed 512MB even if host has 16GB
